from abc import ABC, abstractmethod

class Animal(ABC):
    @property
    @abstractmethod
    def sound(self):           # abstract property
        pass

    @abstractmethod
    def move(self):
        pass

    def describe(self):
        return f"{type(self).__name__} says {self.sound} and {self.move()}"

class Dog(Animal):
    @property
    def sound(self): return 'Woof'
    def move(self):  return 'runs'

class Bird(Animal):
    @property
    def sound(self): return 'Tweet'
    def move(self):  return 'flies'

animals = [Dog(), Bird()]
for a in animals:
    print(a.describe())
# Dog says Woof and runs
# Bird says Tweet and flies

