import functools
import time

# Basic decorator
def timer(func):
    @functools.wraps(func)     # preserve original metadata
    def wrapper(*args, **kwargs):
        start  = time.time()
        result = func(*args, **kwargs)
        end    = time.time()
        print(f"{func.__name__} took {end-start:.4f}s")
        return result
    return wrapper

def logger(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        print(f"Calling {func.__name__} with args={args}")
        result = func(*args, **kwargs)
        print(f"{func.__name__} returned {result}")
        return result
    return wrapper

# Stacking decorators — applied bottom-up: logger first, then timer
@timer
@logger
def add(a, b):
    return a + b

add(3, 4)
# Calling add with args=(3, 4)
# add returned 7
# add took 0.0001s

print(add.__name__)  # add  (preserved by functools.wraps)

import functools

# Decorator with arguments — needs 3 levels
def repeat(n):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for _ in range(n):
                result = func(*args, **kwargs)
            return result
        return wrapper
    return decorator

@repeat(3)
def greet(name):
    print(f"Hello, {name}!")

greet('Alice')   # Hello, Alice! (printed 3 times)

# Memoisation decorator
def memoize(func):
    cache = {}
    @functools.wraps(func)
    def wrapper(*args):
        if args not in cache:
            cache[args] = func(*args)
        return cache[args]
    return wrapper

@memoize
def fib(n):
    if n <= 1: return n
    return fib(n-1) + fib(n-2)

print(fib(50))   # 12586269025 — instant

# Input validation decorator
def validate_positive(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        if any(a <= 0 for a in args if isinstance(a, (int,float))):
            raise ValueError('All arguments must be positive')
        return func(*args, **kwargs)
    return wrapper

@validate_positive
def area(w, h):
    return w * h

print(area(4, 5))   # 20
# area(-1, 5)       # ValueError

# Iterator Protocol — __iter__ and __next__
class CountUp:
    def __init__(self, start, stop):
        self.current = start
        self.stop    = stop

    def __iter__(self):
        return self          # the object itself is the iterator

    def __next__(self):
        if self.current >= self.stop:
            raise StopIteration   # signal end of iteration
        val = self.current
        self.current += 1
        return val

for n in CountUp(1, 6):
    print(n, end=' ')   # 1 2 3 4 5

print(list(CountUp(0, 4)))  # [0, 1, 2, 3]

# Context Manager — __enter__ and __exit__
class Timer:
    import time
    def __enter__(self):
        self.start = __import__('time').time()
        return self             # value bound to 'as' variable

    def __exit__(self, exc_type, exc_val, exc_tb):
        elapsed = __import__('time').time() - self.start
        print(f'Elapsed: {elapsed:.4f}s')
        return False            # False = do not suppress exceptions

with Timer() as t:
    total = sum(range(1000000))
print(total)   # 499999500000 + Elapsed: 0.xxs

# Singleton — only one instance ever created
class Singleton:
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

    def __init__(self):
        self.value = 42

a = Singleton()
b = Singleton()
print(a is b)        # True — same object
print(id(a), id(b))  # same id

# Factory Method — create objects without specifying exact class
class Notification:
    def send(self, msg): raise NotImplementedError

class EmailNotification(Notification):
    def send(self, msg): print(f'Email: {msg}')

class SMSNotification(Notification):
    def send(self, msg): print(f'SMS: {msg}')

class PushNotification(Notification):
    def send(self, msg): print(f'Push: {msg}')

def notification_factory(channel):
    channels = {
        'email': EmailNotification,
        'sms':   SMSNotification,
        'push':  PushNotification
    }
    cls = channels.get(channel.lower())
    if not cls: raise ValueError(f'Unknown channel: {channel}')
    return cls()

n = notification_factory('email')
n.send('Hello!')   # Email: Hello!

# Observer Pattern — event-driven notification
class EventSystem:
    def __init__(self):
        self._listeners = {}   # event → list of callbacks

    def subscribe(self, event, callback):
        self._listeners.setdefault(event, []).append(callback)

    def emit(self, event, data=None):
        for cb in self._listeners.get(event, []):
            cb(data)

events = EventSystem()
events.subscribe('login', lambda d: print(f'Log: user {d} logged in'))
events.subscribe('login', lambda d: print(f'Welcome back, {d}!'))
events.emit('login', 'Alice')
# Log: user Alice logged in
# Welcome back, Alice!

# Strategy Pattern — interchangeable algorithms
class Sorter:
    def __init__(self, strategy):
        self.strategy = strategy

    def sort(self, data):
        return self.strategy(data)

# Strategies are just functions (or lambdas)
asc_sorter  = Sorter(sorted)
desc_sorter = Sorter(lambda d: sorted(d, reverse=True))
len_sorter  = Sorter(lambda d: sorted(d, key=len))

words = ['banana', 'apple', 'cherry', 'date']
print(asc_sorter.sort(words))   # ['apple','banana','cherry','date']
print(desc_sorter.sort(words))  # ['date','cherry','banana','apple']
print(len_sorter.sort(words))   # ['date','apple','banana','cherry']

