# __init_subclass__ — hook called when class is subclassed
class Plugin:
    registry = {}

    def __init_subclass__(cls, plugin_name=None, **kwargs):
        super().__init_subclass__(**kwargs)
        if plugin_name:
            Plugin.registry[plugin_name] = cls
            print(f'Registered plugin: {plugin_name}')

class JSONPlugin(Plugin, plugin_name='json'):
    def process(self): return 'json output'

class XMLPlugin(Plugin, plugin_name='xml'):
    def process(self): return 'xml output'

print(Plugin.registry)  # {'json': JSONPlugin, 'xml': XMLPlugin}
Plugin.registry['json']().process()  # 'json output'

# Descriptor protocol — powers @property
class Validator:
    def __set_name__(self, owner, name):
        self.name = name

    def __get__(self, obj, objtype=None):
        if obj is None: return self
        return obj.__dict__.get(self.name)

    def __set__(self, obj, value):
        if not isinstance(value, int) or value < 0:
            raise ValueError(f'{self.name} must be non-negative int')
        obj.__dict__[self.name] = value

class Product:
    price    = Validator()
    quantity = Validator()

    def __init__(self, price, quantity):
        self.price    = price
        self.quantity = quantity

p = Product(10, 5)
print(p.price, p.quantity)  # 10 5
# Product(-1, 5)             # ValueError
